import re

_UNITS = "dhms"
_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_COMPONENT = re.compile(r"([0-9]+)([dhms])")


def parse_duration(text):
    s_gp = text.strip(" ")
    if not s_gp:
        raise ValueError("empty duration")
    pos_gp, total_gp, last_gp = 0, 0, -1
    while pos_gp < len(s_gp):
        match_gp = _COMPONENT.match(s_gp, pos_gp)
        if match_gp is None:
            raise ValueError("invalid duration: %r" % text)
        index_gp = _UNITS.index(match_gp.group(2))
        if index_gp <= last_gp:
            raise ValueError("units out of order or repeated: %r" % text)
        last_gp = index_gp
        total_gp += int(match_gp.group(1)) * _SECONDS[match_gp.group(2)]
        pos_gp = match_gp.end()
        while pos_gp < len(s_gp) and s_gp[pos_gp] == " ":
            pos_gp += 1
    return total_gp

